//! `Havok SDK/run_00e53090` (Xbox PDB source unit), subsystem `Havok SDK`: its functions in
//! FalloutNV.exe 1.4.0.525, translated (docs/ENGINE_CRATE.md).
//!
//! The unit is a small spline library: a four-`float` vector with its operators
//! (`00e53160` to `00e533a0`), a knot-vector search and the B-spline basis-function
//! evaluators (`00e53830`, `00e538a0`, `00e53a80`), the curve and surface objects built on them
//! and their serialisers (`00e54110` onwards). None of the class names is confirmed from the
//! exe, so every function is `fn_<address>` and described by what its body does.
//!
//! The x87 code is transcribed instruction by instruction on [`Fpu`], whose arithmetic takes
//! the x87 choice of NaN from the prelude's `x87_add` and friends. Functions that keep arrays
//! in their own stack frame run on a block of engine memory laid out as the exe's frame
//! (`Engine::with_stack`), so pointer arithmetic between the frame and the caller's arrays is
//! the exe's own.

#[allow(unused_imports)]
use crate::prelude::*;

/// Largest value the x87 stack holds at once.
const FPU_DEPTH: usize = 8;

/// The x87 register stack, one `f64` per register (the exe's precision control is double:
/// `docs/ENGINE_CRATE.md`). `ST0` is the last element. Every method is one instruction of the
/// exe, named after it; register operands are `ST(i)` indexes as the exe writes them, memory
/// operands are the bit patterns the instruction reads (`FLD dword` quiets a signalling NaN,
/// an arithmetic memory operand does not: `x87_m32`).
#[derive(Debug, Default)]
pub(crate) struct Fpu {
    regs: Vec<f64>,
}

/// The high byte of the x87 status word after a compare (`FNSTSW AX`'s `AH`): `C0` is 1, `C2`
/// is 4 and `C3` is 0x40; an unordered pair sets all three.
pub(crate) fn compare_status(a: f64, b: f64) -> u8 {
    if a.is_nan() || b.is_nan() {
        0x45
    } else if a > b {
        0x00
    } else if a < b {
        0x01
    } else {
        0x40
    }
}

/// The parity flag `TEST AH, mask` leaves: set when the masked byte has an even number of bits
/// (`JP` jumps when it is set, `JNP` when it is not).
pub(crate) fn parity_even(value: u8, mask: u8) -> bool {
    (value & mask).count_ones() % 2 == 0
}

impl Fpu {
    pub(crate) fn new() -> Self {
        Self::default()
    }

    /// `ST(i)`.
    pub(crate) fn st(&self, i: usize) -> f64 {
        self.regs[self.regs.len() - 1 - i]
    }

    fn set(&mut self, i: usize, value: f64) {
        let at = self.regs.len() - 1 - i;
        self.regs[at] = value;
    }

    fn push(&mut self, value: f64) {
        assert!(self.regs.len() < FPU_DEPTH, "x87 stack overflow");
        self.regs.push(value);
    }

    /// `FSTP ST0`.
    pub(crate) fn pop(&mut self) {
        self.regs.pop().expect("x87 stack underflow");
    }

    /// `FLD dword`.
    pub(crate) fn fld_m32(&mut self, bits: u32) {
        self.push(x87_load32(bits));
    }

    /// `FIMUL`: `ST0 = ST0 * value` (the integer converted exactly).
    pub(crate) fn fmul_value(&mut self, value: f64) {
        let product = x87_mul(self.st(0), value);
        self.set(0, product);
    }

    /// `FLD ST(i)`.
    pub(crate) fn fld_st(&mut self, i: usize) {
        let value = self.st(i);
        self.push(value);
    }

    pub(crate) fn fld1(&mut self) {
        self.push(1.0);
    }

    pub(crate) fn fldz(&mut self) {
        self.push(0.0);
    }

    /// `FILD dword`.
    pub(crate) fn fild_m32(&mut self, value: i32) {
        self.push(f64::from(value));
    }

    /// `FST dword`: the word stored.
    pub(crate) fn fst_m32(&self) -> u32 {
        x87_store32(self.st(0))
    }

    /// `FSTP dword`.
    pub(crate) fn fstp_m32(&mut self) -> u32 {
        let bits = self.fst_m32();
        self.pop();
        bits
    }

    /// `FST qword`.
    pub(crate) fn fst_m64(&self) -> u64 {
        self.st(0).to_bits()
    }

    /// `FSTP qword`.
    pub(crate) fn fstp_m64(&mut self) -> u64 {
        let bits = self.fst_m64();
        self.pop();
        bits
    }

    /// `FSTP ST(i)`: copies `ST0` to `ST(i)` and pops.
    pub(crate) fn fstp_st(&mut self, i: usize) {
        let value = self.st(0);
        self.set(i, value);
        self.pop();
    }

    /// `FXCH ST(i)`.
    pub(crate) fn fxch(&mut self, i: usize) {
        let top = self.st(0);
        let other = self.st(i);
        self.set(0, other);
        self.set(i, top);
    }

    /// `FCHS`.
    pub(crate) fn fchs(&mut self) {
        let value = -self.st(0);
        self.set(0, value);
    }

    /// `FABS`.
    pub(crate) fn fabs(&mut self) {
        let value = self.st(0).abs();
        self.set(0, value);
    }

    /// `ST(dst) = ST(dst) + ST(src)`.
    pub(crate) fn fadd(&mut self, dst: usize, src: usize) {
        let value = x87_add(self.st(dst), self.st(src));
        self.set(dst, value);
    }

    /// `ST(dst) = ST(dst) - ST(src)`.
    pub(crate) fn fsub(&mut self, dst: usize, src: usize) {
        let value = x87_sub(self.st(dst), self.st(src));
        self.set(dst, value);
    }

    /// `ST(dst) = ST(src) - ST(dst)`.
    pub(crate) fn fsubr(&mut self, dst: usize, src: usize) {
        let value = x87_sub(self.st(src), self.st(dst));
        self.set(dst, value);
    }

    /// `ST(dst) = ST(dst) * ST(src)`.
    pub(crate) fn fmul(&mut self, dst: usize, src: usize) {
        let value = x87_mul(self.st(dst), self.st(src));
        self.set(dst, value);
    }

    /// `ST(dst) = ST(dst) / ST(src)`.
    pub(crate) fn fdiv(&mut self, dst: usize, src: usize) {
        let value = x87_div(self.st(dst), self.st(src));
        self.set(dst, value);
    }

    /// `ST(dst) = ST(src) / ST(dst)`.
    pub(crate) fn fdivr(&mut self, dst: usize, src: usize) {
        let value = x87_div(self.st(src), self.st(dst));
        self.set(dst, value);
    }

    /// `FADDP ST(i),ST0`.
    pub(crate) fn faddp(&mut self, i: usize) {
        self.fadd(i, 0);
        self.pop();
    }

    /// `FSUBP ST(i),ST0`: `ST(i) = ST(i) - ST0`.
    pub(crate) fn fsubp(&mut self, i: usize) {
        self.fsub(i, 0);
        self.pop();
    }

    /// `FSUBRP ST(i),ST0`: `ST(i) = ST0 - ST(i)`.
    pub(crate) fn fsubrp(&mut self, i: usize) {
        self.fsubr(i, 0);
        self.pop();
    }

    /// `FMULP ST(i),ST0`.
    pub(crate) fn fmulp(&mut self, i: usize) {
        self.fmul(i, 0);
        self.pop();
    }

    /// `FDIVP ST(i),ST0`: `ST(i) = ST(i) / ST0`.
    pub(crate) fn fdivp(&mut self, i: usize) {
        self.fdiv(i, 0);
        self.pop();
    }

    /// `FDIVRP ST(i),ST0`: `ST(i) = ST0 / ST(i)`.
    pub(crate) fn fdivrp(&mut self, i: usize) {
        self.fdivr(i, 0);
        self.pop();
    }

    /// `FADD dword ptr`: `ST0 = ST0 + operand`.
    pub(crate) fn fadd_m32(&mut self, bits: u32) {
        let value = x87_add(self.st(0), x87_m32(bits));
        self.set(0, value);
    }

    /// `FSUB dword ptr`: `ST0 = ST0 - operand`.
    pub(crate) fn fsub_m32(&mut self, bits: u32) {
        let value = x87_sub(self.st(0), x87_m32(bits));
        self.set(0, value);
    }

    /// `FMUL dword ptr`: `ST0 = ST0 * operand`.
    pub(crate) fn fmul_m32(&mut self, bits: u32) {
        let value = x87_mul(self.st(0), x87_m32(bits));
        self.set(0, value);
    }

    /// `FDIV dword ptr`: `ST0 = ST0 / operand`.
    pub(crate) fn fdiv_m32(&mut self, bits: u32) {
        let value = x87_div(self.st(0), x87_m32(bits));
        self.set(0, value);
    }

    /// `FDIVR dword ptr`: `ST0 = operand / ST0`.
    pub(crate) fn fdivr_m32(&mut self, bits: u32) {
        let value = x87_div(x87_m32(bits), self.st(0));
        self.set(0, value);
    }

    /// `FADD qword ptr`.
    pub(crate) fn fadd_m64(&mut self, bits: u64) {
        let value = x87_add(self.st(0), f64::from_bits(bits));
        self.set(0, value);
    }

    /// `FMUL qword ptr`.
    pub(crate) fn fmul_m64(&mut self, bits: u64) {
        let value = x87_mul(self.st(0), f64::from_bits(bits));
        self.set(0, value);
    }

    /// `FDIVR qword ptr`: `ST0 = operand / ST0`.
    pub(crate) fn fdivr_m64(&mut self, bits: u64) {
        let value = x87_div(f64::from_bits(bits), self.st(0));
        self.set(0, value);
    }

    /// `FCOM ST(i)` / `FUCOM ST(i)` and `FNSTSW AX`: `AH`.
    pub(crate) fn fcom_st(&self, i: usize) -> u8 {
        compare_status(self.st(0), self.st(i))
    }

    /// `FCOM dword ptr` and `FNSTSW AX`: `AH`.
    pub(crate) fn fcom_m32(&self, bits: u32) -> u8 {
        compare_status(self.st(0), x87_m32(bits))
    }

    /// `FCOM qword ptr` and `FNSTSW AX`: `AH`.
    pub(crate) fn fcom_m64(&self, bits: u64) -> u8 {
        compare_status(self.st(0), f64::from_bits(bits))
    }

    /// `FCOMPP` / `FUCOMPP` and `FNSTSW AX`: compares `ST0` with `ST1`, pops both.
    pub(crate) fn fcompp(&mut self) -> u8 {
        let status = compare_status(self.st(0), self.st(1));
        self.pop();
        self.pop();
        status
    }
}

/// The CRT `ceil` (`00ec9e10`: a `double` on the stack, the answer in `ST0`).
const CRT_CEIL: u32 = 0x00ec_9e10;
/// The CRT square root (`00ec6040`: the argument in `ST0`, the answer in `ST0`).
const CRT_SQRT: u32 = 0x00ec_6040;

/// `FLD dword` followed by `FSTP dword`: the word a float copy through the x87 stack leaves.
fn copied_word(bits: u32) -> u32 {
    x87_quiet_bits(bits)
}

/// The integer flags the branches of the transcribed functions test (`CF`, `ZF`, `SF`, `OF`,
/// `PF`), as the exe's last compare, test or arithmetic instruction left them.
#[derive(Clone, Copy, Default)]
pub(crate) struct Flags {
    pub(crate) zf: bool,
    pub(crate) sf: bool,
    pub(crate) cf: bool,
    pub(crate) of: bool,
    pub(crate) pf: bool,
}

impl Flags {
    fn mask(bits: u32) -> u32 {
        if bits == 32 {
            u32::MAX
        } else {
            (1 << bits) - 1
        }
    }

    fn zsp(&mut self, result: u32, bits: u32) {
        let r = result & Self::mask(bits);
        self.zf = r == 0;
        self.sf = (r >> (bits - 1)) & 1 != 0;
        self.pf = (r as u8).count_ones() % 2 == 0;
    }

    pub(crate) fn add(&mut self, a: u32, b: u32, bits: u32) -> u32 {
        let m = Self::mask(bits);
        let (a, b) = (a & m, b & m);
        let wide = u64::from(a) + u64::from(b);
        let r = (wide as u32) & m;
        self.cf = wide > u64::from(m);
        self.of = (((a ^ r) & (b ^ r)) >> (bits - 1)) & 1 != 0;
        self.zsp(r, bits);
        r
    }

    pub(crate) fn sub(&mut self, a: u32, b: u32, bits: u32) -> u32 {
        let m = Self::mask(bits);
        let (a, b) = (a & m, b & m);
        let r = a.wrapping_sub(b) & m;
        self.cf = a < b;
        self.of = (((a ^ b) & (a ^ r)) >> (bits - 1)) & 1 != 0;
        self.zsp(r, bits);
        r
    }

    fn logic(&mut self, r: u32, bits: u32) -> u32 {
        let r = r & Self::mask(bits);
        self.cf = false;
        self.of = false;
        self.zsp(r, bits);
        r
    }

    pub(crate) fn and(&mut self, a: u32, b: u32, bits: u32) -> u32 {
        self.logic(a & b, bits)
    }

    pub(crate) fn or(&mut self, a: u32, b: u32, bits: u32) -> u32 {
        self.logic(a | b, bits)
    }

    pub(crate) fn xor(&mut self, a: u32, b: u32, bits: u32) -> u32 {
        self.logic(a ^ b, bits)
    }

    /// `INC` and `DEC` leave the carry flag.
    pub(crate) fn inc(&mut self, a: u32, bits: u32) -> u32 {
        let carry = self.cf;
        let r = self.add(a, 1, bits);
        self.cf = carry;
        r
    }

    pub(crate) fn dec(&mut self, a: u32, bits: u32) -> u32 {
        let carry = self.cf;
        let r = self.sub(a, 1, bits);
        self.cf = carry;
        r
    }

    pub(crate) fn shl(&mut self, a: u32, count: u32, bits: u32) -> u32 {
        let m = Self::mask(bits);
        let wide = u64::from(a & m) << count;
        let r = (wide as u32) & m;
        self.cf = (wide >> bits) & 1 != 0;
        self.of = false;
        self.zsp(r, bits);
        r
    }

    pub(crate) fn shr(&mut self, a: u32, count: u32, bits: u32) -> u32 {
        let m = Self::mask(bits);
        let value = a & m;
        let r = value >> count;
        self.cf = (value >> (count - 1)) & 1 != 0;
        self.of = false;
        self.zsp(r, bits);
        r
    }

    pub(crate) fn sar(&mut self, a: u32, count: u32, bits: u32) -> u32 {
        let m = Self::mask(bits);
        let signed = match bits {
            8 => i32::from(a as u8 as i8),
            16 => i32::from(a as u16 as i16),
            _ => a as i32,
        };
        let r = ((signed >> count) as u32) & m;
        self.cf = (signed >> (count - 1)) & 1 != 0;
        self.of = false;
        self.zsp(r, bits);
        r
    }

    /// `IMUL r32, r/m32`: the low 32 bits of the signed product; `CF` and `OF` say whether it
    /// overflowed (the other flags are undefined after it and left alone).
    pub(crate) fn imul(&mut self, a: u32, b: u32) -> u32 {
        let wide = i64::from(a as i32) * i64::from(b as i32);
        let r = wide as i32;
        self.cf = i64::from(r) != wide;
        self.of = self.cf;
        r as u32
    }
}

/// The stand-in for `RDTSC`: the host clock (the exe's uses are profiling time stamps).
pub(crate) fn time_stamp() -> u64 {
    std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|elapsed| elapsed.as_nanos() as u64)
        .unwrap_or(0)
}

// Translated from 00e53090 (decompiled, FalloutNV.exe 1.4.0.525)
/// Factorial of `n` as a 32-bit integer (cdecl, one `int`): 1 for `n <= 0`, the table
/// `1, 1, 2, 6, 24, 120, 720, 5040, 40320, 362880, 3628800` for `n` up to 10, and above that
/// 3628800 times 11, 12, ... `n`, wrapping in 32 bits.
pub fn fn_00e53090(_e: &mut Engine, n: i32) -> i32 {
    const TABLE: [i32; 11] = [1, 1, 2, 6, 24, 120, 720, 5040, 40320, 362_880, 3_628_800];
    if n <= 0 {
        1
    } else if n <= 10 {
        TABLE[n as usize]
    } else {
        let mut product = TABLE[10];
        for factor in 11..=n {
            product = product.wrapping_mul(factor);
        }
        product
    }
}

// Translated from 00e53130 (decompiled, FalloutNV.exe 1.4.0.525)
/// Binomial coefficient (cdecl `n`, `k`): `n! / (k! * (n - k)!)` with the factorial of
/// `00e53090` and 32-bit wrapping products, the division being the signed `IDIV`.
pub fn fn_00e53130(e: &mut Engine, n: i32, k: i32) -> i32 {
    let rest = fn_00e53090(e, n.wrapping_sub(k));
    let partial = fn_00e53090(e, k);
    let divisor = rest.wrapping_mul(partial);
    let dividend = fn_00e53090(e, n);
    if divisor == 0 || (dividend == i32::MIN && divisor == -1) {
        panic!("00e5315c: IDIV divide error ({dividend} / {divisor})");
    }
    dividend / divisor
}

