    #[test]
    fn trial_knot_removal_error() {
        let mut e = Engine::new();
        heap(&mut e);
        crt(&mut e);
        constants(&mut e);
        // a knot that was only inserted can be removed without moving the curve
        let (knots, controls, _) = inserted_bezier(&mut e);
        assert!(fn_00e552f0(&mut e, 4, 3, knots, controls, 1.5, 4, 1).abs() < 1e-6);
        // the interior knots of a real cubic move it
        let (knots, controls) = cubic_curve(&mut e);
        let first = fn_00e552f0(&mut e, 5, 3, knots, controls, 1.0, 4, 1);
        let second = fn_00e552f0(&mut e, 5, 3, knots, controls, 2.0, 5, 1);
        assert!((first - 0.28867492).abs() < 1e-4, "{first}");
        assert!((second - 0.55277085).abs() < 1e-4, "{second}");
    }

    #[test]
    fn removal_errors_of_the_knots() {
        let mut e = Engine::new();
        heap(&mut e);
        crt(&mut e);
        constants(&mut e);
        let (knots, controls) = cubic_curve(&mut e);
        let errors = float_record(&mut e, &[7.0; 10]);
        fn_00e555f0(&mut e, 5, 3, knots, controls, errors, 4, 5);
        let found = floats_of(&e, errors);
        assert!((found[4] - 0.28867492).abs() < 1e-4 && (found[5] - 0.55277085).abs() < 1e-4);
        assert_eq!(found[3], 7.0);
        assert_eq!(found[6], 7.0);
        // knots equal to their neighbour get the large float
        let repeated = float_record(&mut e, &[7.0; 10]);
        fn_00e555f0(&mut e, 5, 3, knots, controls, repeated, 1, 2);
        let found = floats_of(&e, repeated);
        assert_eq!(found[1].to_bits(), 0x7f7f_ffee);
        assert_eq!(found[2].to_bits(), 0x7f7f_ffee);
        assert_eq!(found[0], 7.0);
        assert_eq!(found[3], 7.0);
    }

    #[test]
    fn single_knot_removal_keeps_the_curve() {
        let mut e = Engine::new();
        heap(&mut e);
        crt(&mut e);
        constants(&mut e);
        let (knots, controls, plain) = inserted_bezier(&mut e);
        let params = [0.3f32, 1.2, 2.5];
        let before: Vec<[f32; 4]> = params
            .iter()
            .map(|u| curve_point(&mut e, knots, controls, 4, 3, *u))
            .collect();
        let big = f32::from_bits(0x7f7f_ffee);
        let removed = fn_00e556f0(&mut e, 4, 3, knots, controls, 1.5, 4, 1, 1, big);
        assert_eq!(removed, 1);
        assert_eq!(
            floats_of(&e, knots),
            vec![0.0, 0.0, 0.0, 0.0, 3.0, 3.0, 3.0, 3.0]
        );
        assert_eq!(vectors_of(&e, controls), plain.to_vec());
        for (k, u) in params.iter().enumerate() {
            let after = curve_point(&mut e, knots, controls, 3, 3, *u);
            for l in 0..4 {
                assert!(close(after[l], before[k][l]));
            }
        }
        // a tolerance of zero stops the removal of a knot that moves the curve
        let (knots, controls) = cubic_curve(&mut e);
        assert_eq!(
            fn_00e556f0(&mut e, 5, 3, knots, controls, 2.0, 5, 1, 1, 0.1),
            0
        );
    }

