    #[test]
    fn repeated_knots_are_compacted() {
        let mut e = Engine::new();
        heap(&mut e);
        let knots = float_record(&mut e, &[0.0, 0.0, 0.0, 1.0, 1.0, 2.0, 2.0, 2.0]);
        let r = fn_00e57370(&mut e, knots, 7);
        let kept = floats_of(&e, knots);
        // every knot equal to its upper neighbour is kept once (the pairs 0 0, 1 1, 2 2 twice),
        // then the last knot is appended
        assert_eq!(kept, vec![0.0, 0.0, 1.0, 2.0, 2.0, 2.0]);
        assert_eq!(r, 7 - 5 - 1);
    }

