    #[test]
    fn least_squares_fit_of_the_control_points() {
        let mut e = Engine::new();
        heap(&mut e);
        crt(&mut e);
        constants(&mut e);
        let (knots, controls) = cubic_curve(&mut e);
        let us: Vec<f32> = (0..13).map(|k| 3.0 * k as f32 / 12.0).collect();
        let pts: Vec<[f32; 4]> = us
            .iter()
            .map(|u| curve_point(&mut e, knots, controls, 5, 3, *u))
            .collect();
        let points = vector_record(&mut e, &pts);
        let params = float_record(&mut e, &us);
        let fitted = vector_record(&mut e, &[[0.0; 4]; 6]);
        let out = Ptr::new(e.mem.alloc(8));
        assert_eq!(
            fn_00e57620(&mut e, out, 5, 3, fitted, knots, 12, points, params, 1e-5, 0.01),
            out
        );
        assert_eq!(e.mem.u8(out.addr()), 1);
        let wanted = vectors_of(&e, controls);
        for (got, want) in vectors_of(&e, fitted).iter().zip(&wanted) {
            for l in 0..4 {
                assert!((got[l] - want[l]).abs() < 1e-3, "{got:?} {want:?}");
            }
        }
        // fewer data points than control points: nothing is solved
        fn_00e57620(
            &mut e, out, 5, 3, fitted, knots, 3, points, params, 1e-5, 0.01,
        );
        assert_eq!(e.mem.u8(out.addr()), 0);
    }

    /// Samples of the cubic curve at `count` evenly spaced parameters, as a point record and a
    /// parameter record.
    fn fit_data(e: &mut Engine, count: usize) -> (Ptr, Ptr, Vec<[f32; 4]>, Vec<f32>) {
        let (knots, controls) = cubic_curve(e);
        let us: Vec<f32> = (0..count)
            .map(|k| 3.0 * k as f32 / (count - 1) as f32)
            .collect();
        let pts: Vec<[f32; 4]> = us
            .iter()
            .map(|u| curve_point(e, knots, controls, 5, 3, *u))
            .collect();
        let points = vector_record(e, &pts);
        let params = float_record(e, &us);
        (points, params, pts, us)
    }

    fn empty_record(e: &mut Engine) -> Ptr {
        let rec = e.mem.alloc(0x40);
        e.mem.set_u32(rec + 8, 0x8000_0000);
        Ptr::new(rec)
    }

    /// The largest distance of the fitted curve from the data at the data's parameters.
    fn worst_fit(
        e: &mut Engine,
        knots: Ptr,
        controls: Ptr,
        last: u32,
        pts: &[[f32; 4]],
        us: &[f32],
    ) -> f32 {
        let mut worst = 0.0f32;
        for (p, u) in pts.iter().zip(us) {
            let q = curve_point(e, knots, controls, last as i32, 3, *u);
            let d: f32 = (0..3).map(|l| (q[l] - p[l]).powi(2)).sum::<f32>().sqrt();
            worst = worst.max(d);
        }
        worst
    }

    #[test]
    fn spline_fit_stays_within_the_tolerance() {
        let mut e = Engine::new();
        heap(&mut e);
        crt(&mut e);
        constants(&mut e);
        let (points, params, pts, us) = fit_data(&mut e, 9);
        let last_out = e.mem.alloc(8);
        let knots_out = empty_record(&mut e);
        let controls_out = empty_record(&mut e);
        fn_00e57d60(
            &mut e,
            8,
            points,
            params,
            0,
            3,
            0.05,
            Ptr::new(last_out),
            knots_out,
            controls_out,
        );
        let last = e.mem.u32(last_out);
        assert_eq!(e.mem.u32(controls_out.addr() + 4), last + 1);
        assert_eq!(e.mem.u32(knots_out.addr() + 4), last + 5);
        assert!(worst_fit(&mut e, knots_out, controls_out, last, &pts, &us) < 0.06);
        // the end points are interpolated
        let controls = vectors_of(&e, controls_out);
        assert_eq!(controls[0], pts[0]);
        assert_eq!(controls[last as usize], pts[8]);
    }

    #[test]
    fn spline_fit_with_chord_length_parameters() {
        let mut e = Engine::new();
        heap(&mut e);
        crt(&mut e);
        constants(&mut e);
        let (points, _, pts, _) = fit_data(&mut e, 9);
        let last_out = e.mem.alloc(8);
        let knots_out = empty_record(&mut e);
        let controls_out = empty_record(&mut e);
        fn_00e58210(
            &mut e,
            8,
            points,
            3,
            0.05,
            Ptr::new(last_out),
            knots_out,
            controls_out,
        );
        let last = e.mem.u32(last_out);
        // the chord-length parameters of the samples
        let mut chord = vec![0.0f32];
        for k in 1..9 {
            let d: f32 = (0..3)
                .map(|l| (pts[k][l] - pts[k - 1][l]).powi(2))
                .sum::<f32>()
                .sqrt();
            chord.push(chord[k - 1] + d);
        }
        let total = chord[8];
        let us: Vec<f32> = chord.iter().map(|c| c / total).collect();
        assert!(worst_fit(&mut e, knots_out, controls_out, last, &pts, &us) < 0.06);
        assert_eq!(floats_of(&e, knots_out)[0], 0.0);
        assert_eq!(*floats_of(&e, knots_out).last().unwrap(), 1.0);
    }

